# -*- coding: utf-8 -*-
"""OA-size scenario stories, batch 7: two pointers, sliding window, prefix sum (first half). 250+ words each."""

QUESTIONS = [

{"id": "sc-101", "v": "tp-ends", "alt": ["hs-index"], "dom": "falconry", "diff": "E",
 "title": "The Mews Ledger",
 "story": "The royal mews at Harrowgate keeps its falcons under the care of a master falconer named Ysolde Brandt, a woman whose patience with birds is matched only by her impatience with paperwork. Each autumn the king's stewards demand a reckoning of the leather equipment, and each autumn Ysolde grumbles that the reckoning is a waste of good flying weather. This year, however, there is a genuine puzzle. The mews owns a collection of weighted creance lines, used to tether young peregrines during training flights, and the stewards insist that two lines must be knotted together so that their combined mass equals a prescribed figure, no more and no less, otherwise the tether will drag the bird off its glide.\n\nThe mews ledger records the mass of every creance line, one entry per line, and thanks to a tidy apprentice who once spent a whole winter on the task, the entries are written in ascending order of mass. Several lines share the same mass, because the saddler produced them in matched batches. Ysolde does not care which two lines are chosen, nor how many valid pairs exist; she only needs to know whether the stewards' figure can be met by knotting two different lines, never one line against itself, and if it can, the positions of the two lines in the ledger so that her apprentice can fetch them.\n\nThe saddler, incidentally, is a cousin of the king's cook and talks endlessly about spiced pears. Ysolde has learned to nod and ignore him. The hooded kestrels in the next cage shriek whenever anyone speaks of pears, which is perhaps why the conversation rarely lasts.\n\nInput: the first line holds N, the number of lines in the ledger, and the prescribed figure T. The second line holds N masses, already in ascending order. Output: the two positions (1-based, smaller first), or the word NONE.\n\nConstraints: N up to 2 * 10^5; each mass up to 10^9; T up to 2 * 10^9. The stewards want a method whose effort does not balloon as the ledger grows, and they refuse to allocate extra scratch parchment beyond a few scribbles.",
 "clues": ["the entries are written in ascending order of mass", "knotting two different lines, never one line against itself", "refuse to allocate extra scratch parchment beyond a few scribbles"],
 "decoys": ["is a cousin of the king's cook and talks endlessly about spiced pears", "The hooded kestrels in the next cage shriek whenever anyone speaks of pears"],
 "core": "A sorted list of numbers; find two different entries adding up to a target, using almost no extra memory.",
 "gloss": [("creance", "a long light line used to tether a hawk during training", True), ("mews", "a building where hawks are kept", True), ("peregrine", "a species of falcon", True), ("ascending", "rising from smallest to largest", False), ("prescribed", "laid down as required", True)],
 "why": {"hs-index": "A value-to-position map solves a pair-sum too, but it ignores the sorted order and costs extra memory, both of which the story points at."},
 "tell": "Sorted input plus a pair that must reach a total, with no spare memory, means two ends closing toward the middle."},

{"id": "sc-102", "v": "tp-write", "dom": "tide mills", "diff": "M",
 "title": "The Millwright's Tally",
 "story": "On the estuary of Penhallow there stands the last working tide mill in the county, and its keeper, a gruff man called Osric Thwaite, records the height of the water in the mill pond at every turn of the hour. The recording board is a long plank of numbered slots, and Osric writes one reading into each slot in the order the readings were taken. The trouble is that the board has been fouled: whenever the tide gate stuck, the same reading was chalked into several consecutive slots, and the guild inspector, a pedantic woman named Marguerite Vane, will not countenance repeats lying side by side.\n\nOsric's instruction from the inspector is precise. The plank must be tidied in place. Every reading that differs from the one immediately before it must be kept, in its original order, and packed toward the front of the plank so that the first stretch of the board holds only the distinct runs. Whatever lies beyond that tidied stretch is irrelevant and may contain any rubbish. Osric is to report how many slots now hold the cleaned record. There is no spare plank; the original may not be copied onto another, since the mill's timber allowance was cut last year and the inspector wishes to see the very same board rewritten, not a second one carved.\n\nIt is worth knowing that the mill grinds oats for the village bakery, and the baker, a cheerful widow, delivers a warm loaf every Friday. The loaf is generally the high point of Osric's week. The inspector, who disapproves of baked goods on the premises, has not yet discovered this arrangement.\n\nInput: the first line gives N, the number of slots. The second line gives the N readings, each a whole number. Output: the count of slots in the tidied front stretch, followed by those readings in order.\n\nConstraints: N up to 10^6; readings between -10^9 and 10^9; the extra memory used must not grow with N. Readings that are equal but not adjacent are NOT repeats and must both be kept.",
 "clues": ["The plank must be tidied in place", "packed toward the front of the plank", "the original may not be copied onto another", "Readings that are equal but not adjacent are NOT repeats"],
 "decoys": ["the baker, a cheerful widow, delivers a warm loaf every Friday", "The inspector, who disapproves of baked goods on the premises, has not yet discovered this arrangement"],
 "core": "Compact an array in place so that consecutive duplicates collapse, keeping the original order and reporting the new length.",
 "gloss": [("countenance", "to tolerate or approve of", True), ("pedantic", "overly fussy about small rules", True), ("estuary", "where a river meets the sea", True), ("consecutive", "following one right after another", False), ("fouled", "spoiled or clogged", True)],
 "why": {"hs-seen": "A seen-set would drop equal readings that are far apart, but the story says non-adjacent repeats must be kept."},
 "tell": "Rewrite the same array, keeping some items packed to the front: one cursor reads ahead, another marks where the next kept item goes."},

{"id": "sc-103", "v": "tp-merge", "dom": "bell foundry", "diff": "M",
 "title": "The Two Rosters of Saint Aldric",
 "story": "The abbey of Saint Aldric keeps two separate rosters of the lay brothers who volunteer for the harvest, one drawn up by the cellarer for the wheat fields and one by the almoner for the orchards. Each roster lists the brothers by their seniority number, and each has been written out in strict ascending order, because the abbot insists that a younger brother never be named before an elder. Some brothers volunteered for both labours and therefore appear on each roster; a brother never appears twice on the same one.\n\nBrother Hadrian, the new scribe, has been charged with a task that sounds simple and is not. The abbot wants a single combined notice listing every brother who has volunteered for BOTH labours, so that the cook can prepare a double ration for those who will work from dawn to dusk. The notice must again be in ascending order of seniority. Hadrian is forbidden from rewriting either original roster, for they are bound into the abbey's register and any erasure would be a scandal; he may only read down them. The two rosters are of very different lengths. The wheat roster is long, since the harvest needs many hands, while the orchard roster is short, and Hadrian worries that he will lose his place if he is not careful.\n\nThere is a rumour in the refectory that the almoner pads his orchard roster with the names of brothers who are away on pilgrimage, in the hope that the cook will send extra bread to his table. Nobody has proved it, and the abbot has declined to look into it. The bell tower, meanwhile, is being repaired, and a mason has been tapping at the stonework since Lent.\n\nInput: line one gives A and B, the lengths of the two rosters. Line two gives the A seniority numbers of the wheat roster, line three the B numbers of the orchard roster, each in ascending order. Output: the seniority numbers present on both, ascending.\n\nConstraints: A up to 10^6, B up to 10^3; seniority numbers up to 10^9. The abbot would be annoyed if Hadrian's labour grew with the product of the two lengths.",
 "clues": ["each has been written out in strict ascending order", "Hadrian is forbidden from rewriting either original roster, for they are bound", "he may only read down them", "The abbot would be annoyed if Hadrian's labour grew with the product of the two lengths"],
 "decoys": ["the almoner pads his orchard roster with the names of brothers who are away on pilgrimage", "a mason has been tapping at the stonework since Lent"],
 "core": "Two sorted lists; list the values that occur in both, in order, by walking down them together without copying or rewriting.",
 "gloss": [("cellarer", "the monk in charge of food and drink stores", True), ("almoner", "the monk who distributes charity", True), ("seniority", "rank by length of service", True), ("refectory", "a monks' dining hall", True), ("strict", "with no equal values allowed", False)],
 "why": {"hs-freq": "Counting everyone in a table works, but it needs memory proportional to the long roster and ignores that both rosters are already ordered."},
 "tell": "Two already-ordered sequences, read-only, answer wanted in order, linear effort: advance one cursor on each, moving whichever is behind."},

{"id": "sc-104", "v": "tp-partition", "dom": "ceramic glazing", "diff": "H",
 "title": "The Glaze Shelf at Longmoor",
 "story": "At the Longmoor pottery works the finished tiles are fired in a long kiln, and afterwards every tile is stamped with one of three glaze grades: 0 for the pale celadon, 1 for the middling ochre, and 2 for the deep cobalt. The tiles then sit along a single shelf, left to right, in whatever order the kiln-hands happened to unload them. A visiting dealer from the coast has said that he will buy the whole shelf, but only if the tiles are rearranged so that every pale tile comes first, then every ochre tile, then every cobalt tile, which is how his customers like to see them displayed.\n\nThe foreman, Cuthbert Larkspur, is a man who prizes economy. The shelf is cramped, there is no bench nor table to lay tiles upon in the meantime, and every tile is heavy; he will tolerate swapping two tiles that are already on the shelf, but he will not allow tiles to be set down elsewhere and picked up again. He has also decided, after a bad experience with a cracked cobalt, that each tile may be handled only a handful of times: the shelf must be walked once, from one end to the other, with at most a small, fixed number of tiles in his hands at any moment.\n\nLarkspur's daughter plays the fiddle in the village band, and every evening she practises on the yard wall while the tiles cool. The foreman claims that the noise shakes the glaze, which is nonsense, but the dealer found the music charming. The pottery's cat, an enormous tabby, sleeps in the empty kiln.\n\nInput: line one gives N, the number of tiles on the shelf. Line two gives N integers, each 0, 1 or 2, left to right. Output: the same N integers after the rearrangement, with all 0 first, then all 1, then all 2.\n\nConstraints: N up to 5 * 10^6; only values 0, 1, 2 occur. The method must not count the tiles of each grade and rewrite the shelf from the counts, for the dealer has insisted that the actual tiles be moved in a single walk along the shelf.",
 "clues": ["every pale tile comes first, then every ochre tile, then every cobalt tile", "the shelf must be walked once, from one end to the other", "he will tolerate swapping two tiles that are already on the shelf", "only values 0, 1, 2 occur"],
 "decoys": ["Larkspur's daughter plays the fiddle in the village band", "The pottery's cat, an enormous tabby, sleeps in the empty kiln"],
 "core": "Rearrange an array of three distinct values into three contiguous blocks, by swapping in place, in a single pass.",
 "gloss": [("celadon", "a pale grey-green glaze", True), ("ochre", "a yellowish-brown earth colour", True), ("cobalt", "a deep blue", True), ("economy", "careful use of limited resources", True), ("tolerate", "to accept without objection", False)],
 "why": {"tp-write": "Compacting in place is related, but here nothing is discarded; every item is kept and sorted into three groups, which needs a third boundary."},
 "tell": "Exactly three kinds of item, sorted into blocks, one walk, swaps only: three regions maintained by two boundaries and a scanner."},

{"id": "sc-105", "v": "sw-fixed", "dom": "glaciology", "diff": "E",
 "title": "The Ice Core Log of Station Nordvik",
 "story": "Station Nordvik sits on the shoulder of a glacier so remote that the supply plane lands there twice a year, weather permitting. The resident glaciologist, Dr Ingrid Solheim, has spent a decade drilling cores of ancient ice and measuring how much dust each metre of the core contains. She keeps these measurements in a long numbered column, one value for every consecutive metre of depth, starting at the surface. Dust concentration rises sharply when a volcano has erupted somewhere on the planet, and Ingrid is looking for the most volcanic stretch of the record.\n\nHer funding body has issued a peculiar rule. Any stretch of the core that is to be called a 'volcanic episode' must be exactly K metres thick, no more and no less, since their old instruments sample in blocks of that depth. Ingrid wishes to find which K-metre stretch, taken from the surface downward, holds the greatest total dust. If several stretches tie, she would like the shallowest one. Stretches are allowed to overlap one another, because an eruption does not respect the arbitrary boundaries of her drill runs.\n\nA wider complication is that Ingrid's colleague, a meteorologist named Teodor, claims that every episode corresponds to the winter solstice, and he bores everyone at supper with this theory. The kitchen is stocked mostly with tinned herring and ship's biscuit. The generator coughs during blizzards, but it has never yet failed.\n\nInput: the first line gives N, the number of metres logged, and K. The second line gives N dust readings, each a non-negative whole number. Output: the depth, counted from 1 at the surface, at which the best K-metre stretch begins, and its total.\n\nConstraints: N up to 3 * 10^6; K between 1 and N; each reading up to 10^4. The funding body will run the program on a laptop that cannot spare the time to re-add K numbers for every possible starting depth.",
 "clues": ["must be exactly K metres thick, no more and no less", "which K-metre stretch, taken from the surface downward, holds the greatest total", "cannot spare the time to re-add K numbers for every possible starting depth"],
 "decoys": ["Ingrid's colleague, a meteorologist named Teodor, claims that every episode corresponds to the winter solstice", "The kitchen is stocked mostly with tinned herring and ship's biscuit"],
 "core": "Among all stretches of exactly K consecutive values, find the one with the largest total, without re-adding every stretch from scratch.",
 "gloss": [("glaciologist", "a scientist who studies glaciers", True), ("solstice", "the shortest or longest day of the year", True), ("episode", "a distinct stretch of events", True), ("consecutive", "following one right after another", False), ("overlap", "to share part of the same range", False)],
 "why": {"ps-range": "Prefix sums would answer any range query, but the stretch length never varies, so a moving window needs no table at all."},
 "tell": "One fixed length, every start position: slide the frame one step, add the entering value and drop the leaving one."},

{"id": "sc-106", "v": "sw-longest", "dom": "wine cellars", "diff": "M",
 "title": "The Cellarmaster's Rule of Three",
 "story": "Beneath the manor of Castelrosso lies a vault of barrels that has been tended by nine generations of the same family, and the present cellarmaster, Bartolomea Fiore, is the first to commit its customs to paper. The barrels are laid in a single long aisle, and each is branded with a letter showing the grape of its vintage: A for aglianico, B for barbera, C for canaiolo, and so on through the alphabet, since the manor grows a bewildering number of varieties. The aisle is read from the entrance inward, and the letters are copied into the vault book exactly in that order.\n\nFiore has inherited an old maxim: a tasting flight offered to a guest must never include more than three different grapes, for a palate crowded with more is said to lose its memory of the first sip. A flight is always a run of barrels that are neighbours in the aisle, never skipping any, because the guest walks down the aisle in single file and the cellarmaster pours as they pass. She is asked by the visiting merchant how long a flight could possibly be, that is, the greatest number of barrels in one unbroken run that stays within the maxim.\n\nThe merchant, a man from the northern ports, arrived on a donkey that refused to enter the vault, and the animal now stands in the courtyard eating the rosemary hedge. Fiore has decided to ignore this. The vintage of 1887, famously, turned to vinegar; the barrels from that year are used as doorstops.\n\nInput: the first line gives N, the number of barrels. The second line gives a string of N capital letters, the grapes in aisle order. Output: the length of the longest unbroken run of barrels that contains at most three different letters.\n\nConstraints: N up to 2 * 10^6. The merchant leaves at dusk, and a method that re-examines every possible run from scratch will not finish before he does.",
 "clues": ["never include more than three different grapes", "a run of barrels that are neighbours in the aisle, never skipping any", "the greatest number of barrels in one unbroken run that stays within the maxim"],
 "decoys": ["arrived on a donkey that refused to enter the vault", "The vintage of 1887, famously, turned to vinegar"],
 "core": "The longest stretch of consecutive items containing no more than a fixed number of distinct kinds.",
 "gloss": [("maxim", "a short saying that states a rule", True), ("aglianico", "a southern Italian grape", True), ("palate", "the sense of taste", True), ("vintage", "the year a wine was made", True), ("unbroken", "continuous, with no gap", False)],
 "why": {"sw-fixed": "That fixes the length first; here the length is the thing you want to maximise, bounded by a limit on variety.", "hs-freq": "Counting letters helps inside the solution, but the question asks about a run of neighbours, not the whole aisle."},
 "tell": "Longest run of neighbours obeying a cap on distinct kinds: stretch it while allowed, pull the back in when the cap breaks."},

{"id": "sc-107", "v": "sw-shortest", "dom": "seed bank", "diff": "M",
 "title": "The Arkwright Seed Vault",
 "story": "Deep in a mountain, behind two sealed doors and a corridor that is kept at a steady temperature below freezing, lies the Arkwright Seed Vault, where the species of the world's crops are held in trust against catastrophe. Vault curator Philippa Ostrander oversees the intake of seed packets that arrive by sled from partner stations. Each packet is marked with the number of its species, and the packets are placed on a single long conveyor in precisely the order they arrive, front to back.\n\nThis season a research council has asked for a 'representative sample' of the conveyor. A sample is a run of packets lying side by side on the belt, with none removed from the middle, and it is representative only if it contains at least one packet of every species on a list the council has supplied, say the list of the seven staple crops. Packets of other species may be mixed in, and several packets of a staple species may appear in the same run. The council is billed per packet handled, and so Philippa wants the sample to be as short as it can be: the fewest packets in a single run that still contains every staple at least once.\n\nThe vault's heating is a persistent grievance. The staff wear fingerless gloves and a surprising amount of wool, and the cafeteria has been serving the same lentil stew since the autumn. An engineer from the ministry visits twice a year to bemoan the cost of the lighting.\n\nInput: line one gives N, the number of packets, and M, the number of staple species. Line two gives the M staple species numbers. Line three gives the N species numbers on the belt. Output: the length of the shortest run containing every staple at least once, or -1 if no run does.\n\nConstraints: N up to 10^6; species numbers up to 10^9; M up to 50. The council's invoice must be produced within a few seconds, so Philippa cannot afford to test every possible run separately.",
 "clues": ["a run of packets lying side by side on the belt, with none removed from the middle", "contains at least one packet of every species on a list", "the fewest packets in a single run that still contains every staple at least once"],
 "decoys": ["The staff wear fingerless gloves and a surprising amount of wool", "An engineer from the ministry visits twice a year to bemoan the cost of the lighting"],
 "core": "The shortest stretch of consecutive items that contains every required kind at least once.",
 "gloss": [("curator", "a person who looks after a collection", True), ("catastrophe", "a sudden great disaster", True), ("staple", "a basic, widely used food", True), ("representative", "typical of the whole", True), ("grievance", "a cause of complaint", True)],
 "why": {"sw-longest": "That seeks the biggest run obeying a cap; this seeks the smallest run that meets a demand, so the shrinking happens while the demand is met.", "hs-freq": "A count table is only a helper here; the question is about runs of neighbours."},
 "tell": "Smallest run of neighbours that satisfies a coverage demand: grow until covered, then shrink from the back while still covered."},

{"id": "sc-108", "v": "sw-exact", "dom": "orchestral", "diff": "H",
 "title": "The Quartet Rehearsals of Maestro Valenti",
 "story": "Maestro Cosimo Valenti conducts a chamber orchestra whose repertoire is catalogued in a leather-bound score book running to many hundreds of entries, each entry noting the principal instrument that carries the melody in that piece: viola, oboe, cello, harp, and so forth, each given a code number. The pieces appear in the book in the order Valenti first programmed them, and he has never reshuffled the book, so that it also serves as a record of his career.\n\nThe festival committee has asked for an evening's programme with a very particular character. The pieces performed must form a run of consecutive entries from the book, in book order, and across that run the melody must be carried by exactly K different principal instruments, neither fewer, which would be dull, nor more, which the committee considers fussy. Valenti is amused rather than offended. He would like to know how many distinct runs in his score book would qualify. Two runs count as different if they start or end at different entries, even if they carry the same instruments.\n\nValenti's second cello, a lanky student named Dmitri, is perpetually late, and the maestro has taken to rehearsing the pieces in which cello is silent whenever Dmitri's bus is delayed. The town's bakery supplies almond pastries for the interval, and the harpist has been complaining that they are too sweet. Valenti himself suffers from a bad knee and rests on a cushioned stool.\n\nInput: line one gives N, the number of entries, and K. Line two gives the N instrument code numbers in book order. Output: the number of runs of consecutive entries that contain exactly K different codes.\n\nConstraints: N up to 2 * 10^5; K up to N; codes up to 10^9. The answer may be very large, so print it as a 64-bit integer. The committee has made plain that comparing every run against every other is not an option, since they wish to run the check on a tablet during the interval.",
 "clues": ["must form a run of consecutive entries from the book", "exactly K different principal instruments, neither fewer", "how many distinct runs in his score book would qualify"],
 "decoys": ["Valenti's second cello, a lanky student named Dmitri, is perpetually late", "The town's bakery supplies almond pastries for the interval"],
 "core": "Count the stretches of consecutive items that contain exactly K different kinds.",
 "gloss": [("repertoire", "the set of pieces a performer knows", True), ("catalogued", "listed in an organised record", True), ("principal", "main or leading", True), ("qualify", "to meet the requirement", False), ("distinct", "different from one another", False)],
 "why": {"sw-longest": "That asks for one longest run under a cap, not a count of runs hitting exactly K, which needs the cap run twice and subtracted.", "ps-count": "Counting runs with a hashmap works for sums, but 'exactly K different kinds' is not additive."},
 "tell": "Count runs with exactly K distinct kinds: count runs with at most K, subtract those with at most K minus one."},

{"id": "sc-109", "v": "sw-deque", "dom": "marathon", "diff": "H",
 "title": "The Elevation Chart of the Ridgeway Relay",
 "story": "The Ridgeway Relay is a long-distance footrace run along an ancient chalk track, and its organiser, Hepzibah Crowe, is a retired surveyor with an almost religious devotion to accuracy. Every year she publishes an elevation chart: a long list recording the height of the ground, in metres, at each hundred-metre marker along the course. This year the course is very long indeed, and the chart runs to hundreds of thousands of entries.\n\nThe safety committee wants a 'steepness warning' printed for each stage of the relay. A stage is a run of exactly K consecutive markers, and the committee defines the warning for that stage as the highest ground reached within it, because the runners tire most at their peak. Since the stages overlap, each stage beginning at the next marker after the previous one, the committee requires the warning for every possible stage, in order, starting with the first K markers, then the next K markers shifted by one, and so on to the end of the course.\n\nHepzibah first wrote a program that, for each stage, looked through all K of its markers and picked the highest. This took longer than the race itself. The committee, who run on strong tea and impatience, have asked her to do better. A further observation from the chart: the ground sometimes rises and falls in saw-tooth patterns near the old quarry, and the committee thinks this is why her first attempt was so slow, though in fact it is only that she did the same work again and again.\n\nThe relay's mascot is a woolly sheep named Gareth. Each year a child is chosen to wear the costume, and each year the costume smells faintly of damp.\n\nInput: line one gives N, the number of markers, and K. Line two gives the N heights. Output: N - K + 1 numbers, the highest height within each stage, in order.\n\nConstraints: N up to 10^6; K up to N; heights up to 10^9. Work done per marker must stay roughly constant.",
 "clues": ["A stage is a run of exactly K consecutive markers", "the highest ground reached within it", "the warning for every possible stage, in order", "she did the same work again and again"],
 "decoys": ["The relay's mascot is a woolly sheep named Gareth", "each year the costume smells faintly of damp"],
 "core": "For every window of K consecutive values, report the maximum, without rescanning each window.",
 "gloss": [("surveyor", "a person who measures land", True), ("elevation", "height above sea level", True), ("chalk", "a soft white limestone", True), ("committee", "a group chosen to decide a matter", True), ("consecutive", "following one right after another", False)],
 "why": {"sw-fixed": "A fixed-length frame is right, but a running total will not do: the maximum cannot be updated by simply subtracting the value that leaves.", "hp-topk": "A priority structure gives the biggest too, but it keeps stale entries and costs more than a structure that discards entries which can never again be the largest."},
 "tell": "A fixed frame sliding along and asking for its maximum each step: keep only the entries that could still become the maximum."},

{"id": "sc-110", "v": "ps-range", "dom": "lexicography", "diff": "E",
 "title": "The Dictionary Counters of Vellum Street",
 "story": "The publishing house of Pemberton & Daughters is compiling a vast dictionary, and the work has been divided among a hundred volunteers, each of whom is given a contiguous bundle of the alphabetically sorted headwords. The house's archivist, Winifred Pell, keeps a daybook in which she records, for every single page of the manuscript, the number of definitions written on that page. Pages are numbered from 1 and the daybook lists them in page order, so that the total for any bundle of pages is simply what you would get by adding up that portion of the daybook.\n\nThe trouble is that Winifred is asked questions all day long. The editor-in-chief wishes to know how many definitions lie between pages 410 and 655. The typesetter wishes to know the total between pages 12 and 99. The proofreader wishes to know the total for pages 3000 to 3002. Each question is of the form 'how many definitions from page L to page R, inclusive', and the daybook never changes while the questions are being answered. Winifred has noticed that she adds the same pages over and over, and that her fingers are tired.\n\nThe house's founder, a flamboyant gentleman who dyed his beard green, once claimed that the English language was too large to ever be catalogued, and this claim now hangs framed above Winifred's desk. The office cat sleeps on the radiator and has no opinion on lexicography. The tea is brewed in a samovar acquired at auction.\n\nInput: line one gives N, the number of pages, and Q, the number of questions. Line two gives the N daily counts. Each of the next Q lines gives L and R. Output: for each question, the total number of definitions from page L to page R inclusive.\n\nConstraints: N up to 10^6; Q up to 10^6; counts up to 10^4. The daybook is fixed once and for all before the first question arrives, and answering a question should take about the same time regardless of how wide the range is.",
 "clues": ["how many definitions from page L to page R, inclusive", "the daybook never changes while the questions are being answered", "she adds the same pages over and over", "regardless of how wide the range is"],
 "decoys": ["a flamboyant gentleman who dyed his beard green", "The office cat sleeps on the radiator and has no opinion on lexicography"],
 "core": "A fixed list of numbers and a great many questions about the total of a range; answer each question instantly.",
 "gloss": [("lexicography", "the compiling of dictionaries", True), ("headword", "the word an entry is listed under", True), ("archivist", "someone who keeps records", True), ("inclusive", "counting both ends", False), ("flamboyant", "showy and extravagant", True)],
 "why": {"ps-diff": "That handles many updates and then one read; here nothing changes and there are many reads.", "ps-count": "Counting ranges with a given total is a different question; here each query is just a total."},
 "tell": "Static data, many range-total questions: precompute running totals once, then every answer is one subtraction."},

{"id": "sc-111", "v": "ps-count", "dom": "salt pans", "diff": "H",
 "title": "The Brine Surveys of Marsh Ferrow",
 "story": "The salt pans of Marsh Ferrow are shallow clay ponds in which seawater is left to evaporate under the summer sun, and each evening the saltmaster, a weathered woman called Perpetua Gale, walks the row of pans with a hydrometer and notes whether the brine in each has grown denser or thinner than it was at dawn. She records the change in density for every pan as a signed whole number, positive if the brine thickened, negative if it thinned, zero if it held still, writing the figures down in the order she passes the pans.\n\nThe salt guild has a curious bylaw about quality marks. A 'balanced stretch' is any run of neighbouring pans, at least one pan long, whose recorded changes add to exactly a figure T set by the guild each year. A balanced stretch earns the whole stretch a mark of distinction. Perpetua is asked, once the evening's figures are in, how many balanced stretches the row of pans contains. Stretches that overlap, or that share a starting pan with a different end, are counted as different stretches. She knows that the answer can be large: a row of a hundred thousand pans can hide a staggering number of them, and the guild wants the exact total.\n\nMeanwhile the salt collectors have been arguing with the heron wardens about whose territory the eastern pans fall in. The herons were there first, the wardens say; the salt was there first, the collectors reply; and the herons, indifferent, continue to stand on one leg. A passing pedlar is selling woollen caps of dubious quality at the sluice gate.\n\nInput: line one gives N, the number of pans, and T. Line two gives N signed integers, the density changes in order. Output: the number of runs of neighbouring pans whose changes total exactly T.\n\nConstraints: N up to 10^6; each change between -10^4 and 10^4; T between -10^9 and 10^9. Because changes may be negative, Perpetua cannot assume that extending a stretch moves its total only upward, so a method that cuts off once the total passes T will miss stretches.",
 "clues": ["any run of neighbouring pans, at least one pan long, whose recorded changes add to exactly a figure T", "how many balanced stretches the row of pans contains", "changes may be negative", "cannot assume that extending a stretch moves its total only upward"],
 "decoys": ["The herons were there first, the wardens say", "A passing pedlar is selling woollen caps of dubious quality at the sluice gate"],
 "core": "Count the stretches of consecutive values (negatives allowed) whose total is exactly T.",
 "gloss": [("hydrometer", "an instrument that measures liquid density", True), ("brine", "very salty water", True), ("bylaw", "a rule made by a local body", True), ("signed", "able to be positive or negative", False), ("sluice", "a sliding gate controlling water flow", True)],
 "why": {"sw-exact": "A moving frame needs totals that only rise as the frame widens; negative values break that.", "ps-longest": "That wants the single longest or shortest stretch; here every matching stretch counts."},
 "tell": "Count stretches with an exact total, negatives allowed: running totals plus a tally of how often each earlier total has appeared."},

{"id": "sc-112", "v": "ps-longest", "alt": ["hs-index"], "dom": "apothecary guild", "diff": "H",
 "title": "The Longest Equal Dose",
 "story": "The Guild of Apothecaries at Ravensworth keeps a registry of every compound dispensed from its dispensary, noted in the order they were made. For the purposes of the registry, each compound is recorded as either a stimulant (+1), a sedative (-1), or an inert tonic (0), and the guild's historian, Ambrose Whitlock, has become fascinated by periods of the dispensary's life during which the stimulants and sedatives were in perfect balance. A 'tranquil season', by his definition, is any run of consecutive entries in the registry whose values add up to exactly zero.\n\nWhitlock's ambition is to name the longest tranquil season in the entire registry, so that he may engrave it upon a commemorative plaque; he does not care how many tranquil seasons there were, nor in what order they happened, only for the length of the very longest and, because plaques are expensive, he would like to know where it begins and ends. If several share the longest length, the earliest is the one to be engraved. The registry now holds several hundred thousand entries, and the guild treasurer is aghast at the thought of comparing every beginning against every ending.\n\nThe dispensary's most beloved apprentice, Leocadia, once mistook powdered liquorice for senna and the whole street smelled of aniseed for a week. The mistake is remembered fondly. The guild hall has a famous weathervane shaped like a pestle, and the historian has written three pamphlets about it, of which only one has been read.\n\nInput: line one gives N, the number of registry entries. Line two gives N values, each -1, 0, or +1, in the order of the registry. Output: the length of the longest run of consecutive entries whose values add to zero, and the first and last positions of the earliest such run (1-based), or 0 if none exists.\n\nConstraints: N up to 5 * 10^5. A method that, for every starting entry, scans forward adding until the end, will be too slow for the treasurer's patience. Note that a run need not contain any stimulant or sedative at all: a lone inert entry is a run of total zero.",
 "clues": ["any run of consecutive entries in the registry whose values add up to exactly zero", "name the longest tranquil season in the entire registry", "the earliest is the one to be engraved", "comparing every beginning against every ending"],
 "decoys": ["Leocadia, once mistook powdered liquorice for senna and the whole street smelled of aniseed", "a famous weathervane shaped like a pestle"],
 "core": "Find the longest stretch of consecutive values whose total is zero (and report where it is).",
 "gloss": [("Apothecaries", "an old word for a pharmacist", True), ("sedative", "a drug that calms", True), ("tranquil", "calm and quiet", True), ("registry", "an official list of records", True), ("inert", "having no active effect", True)],
 "why": {"ps-count": "That counts every matching stretch; here only the single longest stretch matters, so you keep the earliest occurrence of each running total.", "sw-longest": "A moving frame fails: the values can be negative, so extending or shrinking does not change the total in a predictable direction."},
 "tell": "Longest stretch with a fixed total, negatives present: remember the first position each running total appeared and compare distances."},

{"id": "sc-113", "v": "ps-2d", "dom": "tapestry conservation", "diff": "H",
 "title": "The Wear Map of the Hartleigh Tapestry",
 "story": "The Hartleigh Tapestry, a vast woven panel depicting the founding of a town that no longer exists, is being studied by a team of textile conservators at the museum of Aldersgate. To measure its condition, the lead conservator, Dr Rosalind Ketteridge, has overlaid the tapestry with a regular grid of R rows and C columns and assigned each square a wear score, a non-negative whole number reflecting how frayed that square is. The scores are held in a table with the same rows and columns as the grid.\n\nThe museum's insurers are a nervous bunch, and over the weeks they have asked for hundreds upon hundreds of assessments. Each assessment names a rectangular block of the tapestry, giving the topmost row, the leftmost column, the bottom row, and the right-hand column of the block, and asks for the total wear across all the squares inside the block, including its borders. Different assessments overlap freely. The table of scores is never altered between assessments; the tapestry is too fragile to be re-measured, and the figures are already frozen into the conservation report.\n\nRosalind has been working through the assessments by hand, adding up every square of every block, and she is beginning to suspect that she is repeating a great deal of arithmetic. The largest block requested covers nearly the whole grid, and she has seen that the same stretch of squares keeps being re-added in assessment after assessment.\n\nMeanwhile, a researcher from the university has claimed that the tapestry depicts a lost harvest festival; the museum director considers the claim charming and unproven. A tea trolley is wheeled past the conservation lab at eleven each morning, and everybody quietly stops what they are doing.\n\nInput: line one gives R, C and Q. The next R lines give the C scores of each row. The next Q lines give four integers: top row, left column, bottom row, right column. Output: for each assessment, the total wear inside the rectangle.\n\nConstraints: R and C up to 2000; Q up to 10^6; scores up to 100. Each answer should arrive in about the same time however large the rectangle is.",
 "clues": ["a rectangular block of the tapestry", "the total wear across all the squares inside the block", "The table of scores is never altered between assessments", "the same stretch of squares keeps being re-added"],
 "decoys": ["a researcher from the university has claimed that the tapestry depicts a lost harvest festival", "A tea trolley is wheeled past the conservation lab at eleven each morning"],
 "core": "A fixed table of numbers and many questions about the total inside rectangles; answer each instantly.",
 "gloss": [("conservator", "a person who preserves and repairs old objects", True), ("tapestry", "a woven picture hung on a wall", True), ("frayed", "worn and with loose threads", True), ("assessment", "an evaluation or measurement", True), ("rectangular", "shaped like a rectangle", False)],
 "why": {"ps-range": "A one-dimensional table of totals answers row-wise queries only; here the questions are about blocks that span rows and columns."},
 "tell": "Many rectangle totals on a table that never changes: precompute cumulative totals from the corner, answer with four lookups."},
]
